"use client";

import { useState, useEffect } from "react";

// Hooks

import { useFetch } from "@/libs/api/useFetch";
import { useTranslation } from "@/hooks/useTranslation";

// Interfaces

interface Language {
  name: string;
  level: string;
  percent: number;
}

interface LanguagesTabProps {
  lang: string;
}

export default function LanguagesPage({ lang }: LanguagesTabProps) {
  // States

  const [languagesList, setLanguagesList] = useState<Language[]>([]);
  const [saving, setSaving] = useState(false);
  const [manualLanguages, setManualLanguages] = useState(true);
  const [error, setError] = useState("");

  // Hooks

  const { t } = useTranslation();

  const { data } = useFetch("get", { endPoint: `/api/resume/languages/` });

  const { mutate: mutateLanguages } = useFetch(
    "put",
    {
      endPoint: `/api/resume/languages/`,
      body: JSON.stringify({ languages: languagesList }),
    },
    { manual: manualLanguages }
  );

  // Functions

  const executeMutation = async () => {
    try {
      await mutateLanguages();
      setManualLanguages(true);
      setError("");
      return { languages: languagesList };
    } catch {
      setError("error_in_storage");
    } finally {
      setSaving(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setManualLanguages(false);
  };

  const addLanguage = () =>
    setLanguagesList([...languagesList, { name: "", level: "", percent: 50 }]);

  const removeLanguage = (i: number) =>
    setLanguagesList(languagesList.filter((_, index) => index !== i));

  useEffect(() => {
    if (data) setLanguagesList(data.languages || []);
  }, [data]);

  useEffect(() => {
    if (!manualLanguages) executeMutation();
  }, [manualLanguages]);

  return (
    <>
      {console.log(languagesList)}

      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50 dark:from-gray-900 dark:to-gray-800 p-4 md:p-8">
        <div className="max-w-7xl mx-auto">
          {/* Header */}
          <div className="mb-8 md:mb-12">
            <h1 className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent mb-3">
              {t("languages")}
            </h1>
            <p className="text-gray-600 dark:text-gray-400 text-base max-w-2xl">
              {t("languages_slogan")}
            </p>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            {/* Sidebar */}
            <div className="lg:col-span-1">
              <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl border border-gray-200 dark:border-gray-700 p-6 sticky top-6">
                <h2 className="text-xl font-semibold mb-6 dark:text-white flex items-center justify-center">
                  <svg
                    className="w-6 h-6 mr-2 text-blue-500"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129"
                    />
                  </svg>
                  {t("languages")}
                </h2>
                <div className="space-y-4 text-center">
                  <div className="bg-blue-50 dark:bg-blue-900/20 rounded-xl p-4 border border-blue-200 dark:border-blue-800">
                    <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                      {languagesList.length}
                    </div>
                    <p className="text-sm text-blue-700 dark:text-blue-300 mt-1">
                      {t("registered_languages")}
                    </p>
                  </div>
                  <div className="bg-green-50 dark:bg-green-900/20 rounded-xl p-4 border border-green-200 dark:border-green-800">
                    <div className="text-lg font-bold text-green-600 dark:text-green-400">
                      {languagesList.filter((l) => l.percent > 85).length}
                    </div>
                    <p className="text-sm text-green-700 dark:text-green-300 mt-1">
                      {t("fluent_language")}
                    </p>
                  </div>
                  <div className="bg-purple-50 dark:bg-purple-900/20 rounded-xl p-4 border border-purple-200 dark:border-purple-800">
                    <p className="text-sm text-purple-700 dark:text-purple-300 font-medium">
                      {t("important_point")}
                    </p>
                    <p className="text-xs text-purple-600 dark:text-purple-400 mt-2 leading-relaxed">
                      {t("important_point_languages")}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {/* Main Content */}
            <div className="lg:col-span-3">
              <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl border border-gray-200 dark:border-gray-700 overflow-hidden">
                {/* Content Header */}
                <div className="px-6 py-5 border-b border-gray-200 dark:border-gray-700 bg-gradient-to-r from-gray-50 to-white dark:from-gray-800 dark:to-gray-700">
                  <div className="flex items-center">
                    <div className="p-2 rounded-xl bg-blue-100 dark:bg-blue-900/30 mr-4">
                      <svg
                        className="w-6 h-6 text-blue-600 dark:text-blue-400"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129"
                        />
                      </svg>
                    </div>
                    <div>
                      <h2 className="text-xl font-bold dark:text-white">
                        {t("manage_languages")}
                      </h2>
                      <p className="text-gray-600 dark:text-gray-400 text-sm mt-1">
                        {t("add_remove_edit")}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Error Message */}
                {error && (
                  <div className="bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 px-6 py-4">
                    {t(error)}
                  </div>
                )}

                {/* Language List */}
                <div className="p-6 md:p-8">
                  {languagesList.length === 0 ? (
                    <div className="text-center py-12">
                      <div className="w-24 h-24 mx-auto mb-4 rounded-2xl bg-gray-100 dark:bg-gray-700 flex items-center justify-center">
                        <svg
                          className="w-12 h-12 text-gray-400"
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={1}
                            d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129"
                          />
                        </svg>
                      </div>
                      <h3 className="text-lg font-semibold text-gray-600 dark:text-gray-400 mb-2">
                        {t("no_languages_registered")}
                      </h3>
                      <p className="text-gray-500 dark:text-gray-500 text-sm mb-6">
                        {t("add_first_language")}
                      </p>
                      <button
                        onClick={addLanguage}
                        className="px-6 py-3 bg-gradient-to-r from-blue-500 to-purple-600 text-white rounded-xl hover:from-blue-600 hover:to-purple-700 transition-all duration-200 shadow-lg font-medium"
                      >
                        {t("add_language")}
                      </button>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {languagesList.map((language, index) => (
                        <div
                          key={index}
                          className="bg-gray-50 dark:bg-gray-700/50 rounded-xl p-6 border border-gray-200 dark:border-gray-600 hover:border-blue-300 dark:hover:border-blue-600 transition-all duration-200 group"
                        >
                          {/* Single Language */}
                          <div className="flex flex-col lg:flex-row lg:items-center gap-6">
                            {/* Language Number */}
                            <div className="flex-shrink-0">
                              <div className="w-14 h-14 rounded-xl bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-bold text-lg shadow-lg">
                                {index + 1}
                              </div>
                            </div>

                            {/* Language Content */}
                            <div className="flex-1 space-y-4">
                              {/* Name and Level */}
                              <div className="grid grid-cols-1 gap-4">
                                <div className="w-full">
                                  <label className="block text-sm font-medium mb-2 dark:text-gray-300">
                                    {t("language_name")}
                                  </label>
                                  <input
                                    type="text"
                                    value={language.name}
                                    onChange={(e) => {
                                      const arr = [...languagesList];
                                      arr[index].name = e.target.value;
                                      setLanguagesList(arr);
                                    }}
                                    placeholder={t("language_name_ex")}
                                    className="w-full p-4 border border-gray-300 dark:border-gray-600 rounded-xl bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all duration-200 shadow-sm"
                                  />
                                </div>
                              </div>

                              {/* Percent */}
                              <div className="space-y-3">
                                <input
                                  type="range"
                                  min={0}
                                  max={100}
                                  step={5}
                                  value={language.percent}
                                  onChange={(e) => {
                                    const arr = [...languagesList];
                                    arr[index].percent = parseInt(
                                      e.target.value
                                    );
                                    setLanguagesList(arr);
                                  }}
                                  className="w-full h-3 bg-gradient-to-r from-red-400 via-yellow-400 to-green-400 rounded-lg appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:h-5 [&::-webkit-slider-thumb]:w-5 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:shadow-lg [&::-webkit-slider-thumb]:border-2 [&::-webkit-slider-thumb]:border-gray-300"
                                />
                                <div className="flex justify-between text-xs text-gray-500 dark:text-gray-400">
                                  <span>{t("beginner")}</span>
                                  <span>{t("intermediate")}</span>
                                  <span>{t("fluent")}</span>
                                  <span>{t("native")}</span>
                                </div>
                              </div>
                            </div>

                            {/* Delete Button */}
                            <div className="flex-shrink-0">
                              <button
                                onClick={() => removeLanguage(index)}
                                className="px-4 py-3 bg-gradient-to-r from-red-500 to-pink-600 text-white rounded-xl hover:from-red-600 hover:to-pink-700 transition-all duration-200 shadow-lg hover:shadow-xl flex items-center font-medium w-full justify-center"
                              >
                                <svg
                                  className="w-4 h-4 mr-2"
                                  fill="none"
                                  stroke="currentColor"
                                  viewBox="0 0 24 24"
                                >
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                                  />
                                </svg>
                              </button>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}

                  {/* Action Buttons */}
                  {languagesList.length > 0 && (
                    <div className="flex flex-col sm:flex-row gap-3 justify-end items-stretch sm:items-center pt-5 mt-6 border-t border-gray-200 dark:border-gray-700">
                      {/* Add More */}
                      <button
                        onClick={addLanguage}
                        className="w-full sm:w-auto px-5 py-3 bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-lg hover:from-green-600 hover:to-emerald-700 transition-all duration-200 shadow-md text-sm flex items-center justify-center"
                      >
                        <svg
                          className="w-4 h-4 ml-2"
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M12 6v6m0 0v6m0-6h6m-6 0H6"
                          />
                        </svg>
                        {t("new")}
                      </button>

                      {/* Save Button */}
                      <button
                        onClick={handleSave}
                        disabled={saving}
                        className="w-full sm:w-auto px-7 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 disabled:from-blue-400 disabled:to-indigo-400 text-white rounded-lg font-medium transition-all duration-200 shadow-md text-sm flex items-center justify-center"
                      >
                        {saving ? (
                          <>
                            <svg
                              className="animate-spin -ml-1 mr-3 h-4 w-4 text-white"
                              fill="none"
                              viewBox="0 0 24 24"
                            >
                              <circle
                                className="opacity-25"
                                cx="12"
                                cy="12"
                                r="10"
                                stroke="currentColor"
                                strokeWidth="4"
                              ></circle>
                              <path
                                className="opacity-75"
                                fill="currentColor"
                                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                              ></path>
                            </svg>
                            {t("saving")}
                          </>
                        ) : (
                          <>
                            <svg
                              className="w-4 h-4 ml-2"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M5 13l4 4L19 7"
                              />
                            </svg>
                            {t("save")}
                          </>
                        )}
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
